A passing design of this technique (line-chart: a line drawn year by year with the ground under it filling behind the pen, the last value landing large beside its point), in this sandbox and on the tokens, for its mechanics, its timing and its standard. It uses: draw on, docking. Its concept came from its own narration: find this slot's own rather than reusing its layout. Its words and figures are its own; yours come from this slot and its claims:
````jsx
// Concept: the floor gives way. The line is drawn down the frame a year at a time as the
// years are spoken, and the ground under it fills behind the pen, so what is left shrinks
// with every year until the last value lands large beside its point.
// Storyboard, on the narration's clock (this slot reads 2019 to 2022):
//   0.0 s  the hook: the baseline draws across, the takeaway and the key rise in above it
//   2.0 s  "2019": the first point lands with its value and year
//   3.8 s  "2020": the line draws down to the next point as the year is said, the area
//          under it filling behind the pen; the point, its value and its year land
//   5.4 s  "2021": the same
//   6.8 s  "2022": the last segment lands, and the last value rises in large beside its
//          point on the hero spring, its unit beside it, the annotation beneath
//   to the end: the chart holds while the camera keeps a slow push
// Only a baseline: no gridlines or ticks, so the line and its values carry the reading.

// The story line's colour says what it did: this sample's price fell, so it is 'collapse'.
// A gain is 'recovery'; a series that neither falls nor rises uses 'neutral' (chartSeries[0]).
const TONE = 'collapse'

// When the narration names a point: the first word that starts with its label.
function spokenAt(point, index, words) {
  const said = words.find((word) => word.text.indexOf(point.x) === 0)
  return said ? said.atMs : motion.ms.enter + index * (motion.ms.draw + motion.ms.gap)
}

// A value as the data states it, with its thousands grouped: 12000 is "12,000", 2.5 stays "2.5".
function formatValue(y) {
  const parts = String(Math.abs(y)).split('.')
  const whole = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',')
  return (y < 0 ? '-' : '') + whole + (parts.length > 1 ? '.' + parts[1] : '')
}

// Helpers, called directly: 0 to 1 over lengthMs from atMs, held at 1, one per curve,
// since each interpolate names its curve in the call.
function range(fps, atMs, lengthMs) {
  return [motion.frames(atMs, fps), motion.frames(atMs + lengthMs, fps)]
}
function arrive(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.enter, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}
function travel(frame, fps, atMs, lengthMs) {
  return Remotion.interpolate(frame, range(fps, atMs, lengthMs), [0, 1], {
    easing: motion.ease.move, extrapolateLeft: 'clamp', extrapolateRight: 'clamp',
  })
}

// The fade with rise, for the words that frame the chart.
function rise(amount, unit) {
  return { opacity: amount, transform: 'translateY(' + (1 - amount) * motion.px.rise * unit + 'px)' }
}

// Each point's place in the plot, on the story's years.
function place(points, years, peak, box) {
  const step = box.w / Math.max(1, years.length - 1)
  return points.map((point, index) => {
    const slot = years.indexOf(point.x)
    return { x: box.x + (slot < 0 ? index : slot) * step, y: box.y + box.h - (peak > 0 ? point.y / peak : 0) * box.h }
  })
}

// How far each segment has drawn: segment i reaches point i as that year is spoken, drawn
// over motion.ms.draw. Returns one 0 to 1 value per point; the first point's is its landing.
function drawnOf(frame, fps, series, landOf) {
  return series.points.map((point, index) =>
    index === 0
      ? arrive(frame, fps, landOf(point.x), motion.ms.enter)
      : arrive(frame, fps, Math.max(0, landOf(point.x) - motion.ms.draw), motion.ms.draw),
  )
}

// The drawn part of a line as a list of spots: every point reached, then the pen's head
// part of the way along the segment it is drawing.
function drawnPath(spots, drawn) {
  const path = [spots[0]]
  for (let index = 1; index < spots.length; index += 1) {
    const done = drawn[index]
    if (done <= 0) break
    const from = spots[index - 1]
    const to = spots[index]
    path.push({ x: from.x + (to.x - from.x) * done, y: from.y + (to.y - from.y) * done })
    if (done < 1) break
  }
  return path
}

function Graphic(props) {
  const frame = Remotion.useCurrentFrame()
  const { width, height, fps } = Remotion.useVideoConfig()
  const { colors, fonts } = props.brand
  const inset = props.safeArea
  const portrait = height > width
  const unit = Math.min(width, height) / 1080
  const all = props.data.series
  const story = all[0]
  const points = story.points
  const years = points.map((point) => point.x)
  const last = points.length - 1
  const lands = points.map((point, index) => spokenAt(point, index, props.words))
  const landOf = (x) => lands[Math.max(0, years.indexOf(x))]
  const note = (props.data.annotations || []).find((item) => item.atX === points[last].x)
  const peak = Math.max(...all.flatMap((series) => series.points.map((point) => point.y)))
  const tone = TONE === 'neutral' ? colors.chartSeries[0] : colors.semantic[TONE]
  const colorOf = (s) => (s === 0 ? tone : colors.chartSeries[s % colors.chartSeries.length])
  const heroText = formatValue(points[last].y)
  const heroSize = (portrait ? 110 : 132) * unit
  // The callout's room on the right, from its own words: about 0.6 em a character at each size.
  const callout = Math.min(
    0.34 * (width - inset.left - inset.right),
    Math.max(heroText.length * 0.6 * heroSize + (10 + story.unit.length * 0.6 * 36) * unit, note ? note.text.length * 0.55 * 40 * unit : 0) + 48 * unit,
  )
  // The plot: room above for the values, below for the years, and to the right for the callout.
  const svgW = width - inset.left - inset.right
  const svgH = (portrait ? 0.46 : 0.56) * height
  const box = { x: 40 * unit, y: 90 * unit, w: svgW - 40 * unit - callout, h: svgH - 170 * unit }
  const baseY = box.y + box.h
  const lines = all.map((series) => place(series.points, years, peak, box))
  const drawn = all.map((series) => drawnOf(frame, fps, series, landOf))
  // motion.order: the baseline (the frame) first, then the title, then the series key.
  const baseline = arrive(frame, fps, 0, motion.ms.draw)
  const titleIn = arrive(frame - motion.stagger(1, fps), fps, 0, motion.ms.enter)
  const keyIn = arrive(frame - motion.stagger(2, fps), fps, 0, motion.ms.enter)
  // The hero: the beat's one spring, as the last point lands; its note one stagger step after.
  const hero = Remotion.spring({ frame, fps, delay: motion.frames(lands[last], fps), config: motion.spring.hero })
  const noted = arrive(frame - motion.stagger(2, fps), fps, lands[last] + motion.ms.enter, motion.ms.enter)
  const push = travel(frame, fps, 0, props.durationMs)
  const align = portrait ? 'center' : 'left'
  const lift = (amount) => 'translate(0 ' + (1 - amount) * motion.px.rise * unit + ')'
  // A value sits above its dot when its line is highest at that year, below otherwise, so two lines' labels
  // part; but never below when that would put it on the years, so a dot near the baseline keeps its label above.
  const highest = (x, y) => all.every((series) => series.points.every((point) => point.x !== x || point.y <= y))
  // The area under the story line, filled behind the pen: the drawn path, down to the baseline and back.
  const storyPath = drawnPath(lines[0], drawn[0])
  const head = storyPath[storyPath.length - 1]
  const area = storyPath.length > 1
    ? storyPath.map((spot, index) => (index === 0 ? 'M ' : 'L ') + spot.x + ' ' + spot.y).join(' ')
      + ' L ' + head.x + ' ' + baseY + ' L ' + storyPath[0].x + ' ' + baseY + ' Z'
    : ''
  const heroSpot = lines[0][last]

  return (
    <Remotion.AbsoluteFill
      style={{
        paddingTop: inset.top, paddingRight: inset.right,
        paddingBottom: inset.bottom, paddingLeft: inset.left,
        justifyContent: 'center', gap: 20 * unit,
        // The plot spans the frame, so the push is small and from the centre: neither edge leaves the inset.
        transform: 'scale(' + (1 + 0.02 * push) + ')', transformOrigin: '50% 60%',
      }}
    >
      <div style={{ fontFamily: fonts.heading, fontSize: 64 * unit, lineHeight: 1.1, color: colors.textPrimary, textAlign: align, ...rise(titleIn, unit) }}>
        {props.data.takeaway}
      </div>
      <div
        style={{
          display: 'flex', flexWrap: 'wrap', gap: 12 * unit + 'px ' + 32 * unit + 'px',
          justifyContent: portrait ? 'center' : 'flex-start', fontFamily: fonts.body, fontSize: 32 * unit,
          color: colors.textSecondary, ...rise(keyIn, unit),
        }}
      >
        {all.map((series, s) => (
          <div key={series.label} style={{ display: 'flex', alignItems: 'center', gap: 12 * unit }}>
            {all.length > 1 ? <div style={{ width: 28 * unit, height: 6 * unit, backgroundColor: colorOf(s) }} /> : null}
            {series.label + ', ' + series.unit}
          </div>
        ))}
      </div>
      <svg width={svgW} height={svgH} viewBox={'0 0 ' + svgW + ' ' + svgH} style={{ overflow: 'visible' }}>
        <line
          x1={box.x} x2={box.x + box.w * baseline} y1={baseY} y2={baseY}
          stroke={Remotion.withAlpha(colors.textSecondary, 0.6)} strokeWidth={3 * unit}
        />
        {area ? <path d={area} fill={Remotion.withAlpha(tone, 0.14)} /> : null}
        {all.map((series, s) => {
          const path = drawnPath(lines[s], drawn[s])
          return path.length > 1 ? (
            <path
              key={'line' + series.label}
              d={path.map((spot, index) => (index === 0 ? 'M ' : 'L ') + spot.x + ' ' + spot.y).join(' ')}
              fill="none" stroke={colorOf(s)} strokeWidth={(s === 0 ? 7 : 4) * unit}
              strokeLinecap="round" strokeLinejoin="round"
            />
          ) : null
        })}
        {all.map((series, s) => series.points.map((point, index) => {
          const landed = arrive(frame, fps, landOf(point.x), motion.ms.enter)
          const spot = lines[s][index]
          const isHero = s === 0 && index === last
          const above = highest(point.x, point.y) || spot.y + 60 * unit > baseY
          return (
            <g key={series.label + point.x}>
              <circle cx={spot.x} cy={spot.y} r={(isHero ? 14 : 10) * unit} opacity={landed}
                fill={s === 0 && !isHero ? colors.textPrimary : colorOf(s)} />
              {isHero ? null : (
                <text x={spot.x} y={spot.y + (above ? -28 : 54) * unit} textAnchor="middle" opacity={landed}
                  transform={lift(landed)} fill={colors.textPrimary}
                  fontFamily={fonts.numbers} fontSize={42 * unit}>
                  {formatValue(point.y)}
                </text>
              )}
            </g>
          )
        }))}
        {points.map((point, index) => {
          const landed = arrive(frame, fps, lands[index], motion.ms.enter)
          return (
            <text key={'year' + point.x} x={lines[0][index].x} y={baseY + 62 * unit} textAnchor="middle"
              opacity={landed} transform={lift(landed)} fill={colors.textSecondary}
              fontFamily={fonts.body} fontSize={32 * unit}>
              {point.x}
            </text>
          )
        })}
        <text
          x={heroSpot.x + 34 * unit} y={heroSpot.y - 18 * unit} opacity={Math.min(1, Math.max(0, hero))}
          transform={'translate(0 ' + (1 - hero) * motion.px.rise * 2 * unit + ')'}
          fill={tone} fontFamily={fonts.numbers} fontSize={heroSize}>
          {heroText}
          <tspan fontSize={36 * unit} fill={colors.textSecondary} dx={10 * unit}>{story.unit}</tspan>
        </text>
        {note ? (
          <text x={heroSpot.x + 34 * unit} y={heroSpot.y + 40 * unit} opacity={noted} transform={lift(noted)}
            fill={colors.textPrimary} fontFamily={fonts.title} fontSize={40 * unit}>
            {note.text}
          </text>
        ) : null}
      </svg>
    </Remotion.AbsoluteFill>
  )
}

````
